-- =====================================================================
-- SIAP ARU v1.6.5 - OPTIONAL IMPORT CURRENT FORM PERSURATAN ARU
-- Source: Form Persuratan ARU.xlsx (uploaded by user)
-- Focus: PKS, Direksi, Bag. Operasional, PO, Bag. Umum. Kwitansi excluded.
-- Prepared rows: 1247. Missing-date source rows skipped: 6.
-- Run migration_v1.6.4_to_v1.6.5_persuratan_excel_ui.sql FIRST.
-- Safe to re-run: legacy_import_key = source sheet + row.
-- =====================================================================
USE `aru_siap`;
SET @root_id := (
  SELECT id FROM `aru_siap`.`siap_users`
  WHERE role='ROOT_ADMIN' ORDER BY created_at ASC LIMIT 1
);

DROP TEMPORARY TABLE IF EXISTS `tmp_aru_persuratan_import`;
CREATE TEMPORARY TABLE `tmp_aru_persuratan_import` (
  sheet_order INT NOT NULL,
  sheet_name VARCHAR(150) NOT NULL,
  row_no INT NOT NULL,
  document_type VARCHAR(80) NOT NULL,
  format_code VARCHAR(40) NOT NULL,
  prefix_text VARCHAR(20) NOT NULL,
  raw_number VARCHAR(80) NOT NULL,
  seq_base INT NULL,
  variant INT NULL,
  letter_date DATE NOT NULL,
  legacy_user_input VARCHAR(180) NULL,
  recipient VARCHAR(255) NULL,
  subject VARCHAR(500) NOT NULL,
  legacy_file_url TEXT NULL,
  legacy_status VARCHAR(20) NOT NULL,
  legacy_import_key VARCHAR(255) NOT NULL,
  PRIMARY KEY (legacy_import_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;















UPDATE `aru_siap`.`siap_letters` l
JOIN `tmp_aru_persuratan_import` s ON s.legacy_import_key=l.legacy_import_key
JOIN `aru_siap`.`siap_number_formats` nf ON nf.code=s.format_code
SET l.document_type=s.document_type,l.number_format_id=nf.id,
    l.letter_number=CONCAT(s.prefix_text,'/',s.raw_number,'/AR/',YEAR(s.letter_date)),
    l.recipient=s.recipient,l.subject=s.subject,l.letter_date=s.letter_date,l.issued_date=s.letter_date,
    l.status=s.legacy_status,l.current_role=NULL,l.is_public=1,l.is_backdated=(s.letter_date<CURDATE()),
    l.cancelled_reason=IF(s.legacy_status='CANCELLED','BATAL pada workbook sumber',NULL),
    l.legacy_number_text=s.raw_number,l.legacy_user_input=s.legacy_user_input,l.legacy_file_url=s.legacy_file_url,
    l.legacy_sheet_name=s.sheet_name,l.legacy_row_no=s.row_no,l.updated_by=@root_id;

 letter_date,received_date,issued_date,confidentiality,summary,notes,status,current_role,current_owner_user_id,
 is_public,is_backdated,cancelled_reason,legacy_import_key,legacy_number_text,legacy_user_input,legacy_file_url,
 legacy_sheet_name,legacy_row_no,legacy_number_conflict,created_by,updated_by)
SELECT UUID(),'OUTGOING',s.document_type,nf.id,
       CONCAT(s.prefix_text,'/',s.raw_number,'/AR/',YEAR(s.letter_date)),
       NULL,s.subject,NULL,s.recipient,s.letter_date,NULL,s.letter_date,'BIASA',NULL,
       CONCAT('Import historis dari ',s.sheet_name,' baris ',s.row_no,'.'),
       s.legacy_status,NULL,NULL,1,(s.letter_date<CURDATE()),
       IF(s.legacy_status='CANCELLED','BATAL pada workbook sumber',NULL),
       s.legacy_import_key,s.raw_number,s.legacy_user_input,s.legacy_file_url,s.sheet_name,s.row_no,0,@root_id,@root_id
FROM `tmp_aru_persuratan_import` s
JOIN `aru_siap`.`siap_number_formats` nf ON nf.code=s.format_code
LEFT JOIN `aru_siap`.`siap_letters` l ON l.legacy_import_key=s.legacy_import_key
WHERE l.id IS NULL;

SELECT UUID(),l.id,@root_id,'IMPORT_LEGACY_EXCEL',NULL,l.status,CONCAT('Import ',s.sheet_name,' baris ',s.row_no)
FROM `tmp_aru_persuratan_import` s
JOIN `aru_siap`.`siap_letters` l ON l.legacy_import_key=s.legacy_import_key
LEFT JOIN `aru_siap`.`siap_letter_actions` a ON a.letter_id=l.id AND a.action='IMPORT_LEGACY_EXCEL'
WHERE a.id IS NULL;

SELECT UUID(),nf.id,l.id,YEAR(s.letter_date),s.letter_date,s.seq_base,s.variant,
       CONCAT(s.prefix_text,'/',s.raw_number,'/AR/',YEAR(s.letter_date)),
       IF(s.legacy_status='CANCELLED','CANCELLED','ISSUED'),
       IF(s.legacy_status='CANCELLED','BATAL pada workbook sumber',NULL),@root_id
FROM `tmp_aru_persuratan_import` s
JOIN `aru_siap`.`siap_number_formats` nf ON nf.code=s.format_code
JOIN `aru_siap`.`siap_letters` l ON l.legacy_import_key=s.legacy_import_key
LEFT JOIN `aru_siap`.`siap_number_ledger` already ON already.letter_id=l.id
WHERE s.seq_base IS NOT NULL AND s.variant IS NOT NULL AND already.id IS NULL
ORDER BY s.sheet_order,s.row_no;

UPDATE `aru_siap`.`siap_letters` l
JOIN `tmp_aru_persuratan_import` s ON s.legacy_import_key=l.legacy_import_key
LEFT JOIN `aru_siap`.`siap_number_ledger` nl ON nl.letter_id=l.id
SET l.legacy_number_conflict=CASE WHEN s.seq_base IS NULL OR s.variant IS NULL OR nl.id IS NULL THEN 1 ELSE 0 END;

VALUES (@root_id,'OUTGOING_EXCEL_IMPORT_SEED','LETTER',NULL,
 JSON_OBJECT('source','Form Persuratan ARU.xlsx','prepared_rows',1247,'skipped_missing_date',6));

SELECT COUNT(*) AS imported_or_updated_rows,
       SUM(legacy_number_conflict=1) AS historical_number_conflicts
FROM `aru_siap`.`siap_letters`
WHERE legacy_import_key LIKE 'ARU_XLSX:%';

SELECT nf.code,nf.name,COUNT(nl.id) AS ledger_rows,MAX(nl.seq_base) AS max_base_2026
FROM `aru_siap`.`siap_number_formats` nf
LEFT JOIN `aru_siap`.`siap_number_ledger` nl ON nl.format_id=nf.id AND nl.number_year=2026
WHERE nf.code IN ('PKS','DIR','OPS','PO','UMUM')
GROUP BY nf.id,nf.code,nf.name
ORDER BY FIELD(nf.code,'PKS','DIR','OPS','PO','UMUM');

DROP TEMPORARY TABLE IF EXISTS `tmp_aru_persuratan_import`;
